<?php require_once "config/database.php";require_once "includes/functions.php";$q=trim($_GET["q"]??"");$sql="SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='active'";$args=[];if($q!==""){$sql.=" AND (p.name LIKE ? OR p.brand LIKE ? OR p.oem_number LIKE ?)";$x="%$q%";$args=[$x,$x,$x];}$st=$pdo->prepare($sql." ORDER BY p.id DESC");$st->execute($args);$products=$st->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products | JKtech.lk</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/navbar.php";?><main class="container page"><span class="eyebrow">AUTOMOTIVE PARTS</span><h1>Find the right part.</h1><form class="searchbar"><input name="q" value="<?=e($q)?>" placeholder="Search part, brand or OEM number..."><button class="btn primary">Search</button></form><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><div class="product-art">JKT</div><div class="product-body"><small><?=e($p["brand"])?> · <?=e($p["category_name"]??"Parts")?></small><h3><?=e($p["name"])?></h3><p>OEM: <?=e($p["oem_number"]??"N/A")?> · Stock: <?=$p["stock"]?></p><div class="product-foot"><strong>Rs. <?=number_format($p["price"],2)?></strong><a class="add" href="product-details.php?id=<?=$p["id"]?>">Details</a></div></div></article><?php endforeach;?></div></main></body></html>